-- Generated by model/lib/sql/generate.mjs. Loads Price Increase IN from cells/Price Increase IN.csv in the folder of input cells. Two rows for one cell add up.
INSERT INTO "Price Increase IN" ("Brand", "Versions", "Years", v, ver, is_deleted) SELECT coalesce(k0."Brand", throwIf(isNull(k0."Brand"), 'cells name a member Brand does not have')), coalesce(k1."Versions", throwIf(isNull(k1."Versions"), 'cells name a member Versions does not have')), coalesce(k2."Years", throwIf(isNull(k2."Years"), 'cells name a member Years does not have')), sum(toFloat64(c.value)), toUnixTimestamp64Micro(now64(6)), 0
FROM file('cells/Price Increase IN.csv', 'CSVWithNames', '"Brand" String, "Versions" String, "Years" String, "value" String') c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
